import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Korisnik {
  id: number;
  ime: string;
  username: string;
  email: string;
  ulogas: []
}

@Injectable({
  providedIn: 'root'
})
export class AdminService {
  private apiUrl = '/api/auth/admin';

  constructor(private http: HttpClient) { }

  getUsers(): Observable<Korisnik[]> {
    return this.http.get<Korisnik[]>(`${this.apiUrl}/users`);
  }

  getUser(userId: number): Observable<Korisnik> {
    return this.http.get<Korisnik>(`${this.apiUrl}/users/${userId}`);
  }

  updateUser(user: Korisnik): Observable<void> {
    return this.http.put<void>(`${this.apiUrl}/users/${user.id}`, user);
  }

  deleteUser(userId: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/users/${userId}`);
  }
}
